  ],
  "fsm_states": ["IDLE", "LOAD", "COMPARE", "DONE"],
  "critical_nodes": [
    {
      "signal": "sig_shift",
      "reason": "sig_shift accumulates the incoming signature bytes over the LOAD state and is compared against expected_sig in COMPARE. Since it holds the raw signature data, faulting it during LOAD could corrupt the assembled signature value seen at COMPARE time.",
      "exploit_scenario": "An attacker injects a single-cycle transient fault that forces one or more bits of sig_shift to a chosen value during the LOAD state, altering the assembled signature before COMPARE evaluates sig_shift == expected_sig. If the attacker can predict expected_sig, they could theoretically force sig_shift to match it bit-by-bit across multiple LOAD cycles, causing the comparison to succeed and boot_allowed to assert."
    },
    {
      "signal": "state",
      "reason": "state is the FSM control register whose encoding selects which branch of the always @(posedge clk) block executes, including whether COMPARE ever runs before DONE is reached. The DONE state directly drives the boot-allowed/done output based on auth_ok.",
      "exploit_scenario": "An attacker with fault-injection access forces the state register directly into the DONE encoding for one clock cycle while byte_count/sig_shift are still mid-load or garbage, skipping the COMPARE state entirely so auth_ok <= (sig_shift == expected_sig) is never (re)evaluated on valid data. If auth_ok still holds a stale or forced value of 1, done/boot-allowed asserts immediately with no valid signature ever compared. This is a second, independent primary bypass vector, distinct from data-path registers such as sig_shift or byte_count, which merely feed the comparison and cannot themselves cause a skip of COMPARE."
    }
  ],
  "hardening_recommendations": [
    {
      "target_signal": "sig_shift",
      "technique": "redundant CRC/checksum validation of sig_shift alongside the raw comparison",
      "rationale": "Adding a checksum over sig_shift lets the design detect a transient corruption of the assembled signature bytes before the COMPARE stage relies on them."
    },
    {
      "target_signal": "state",
      "technique": "Checksum-based state validation with a complementary encoding check (store state alongside its bitwise complement in a shadow register and flag an error if state != ~shadow_state)",
      "rationale": "A single-bit fault that forces state directly into the DONE encoding will not simultaneously produce the correct complementary value in the shadow register, so the encoding-consistency check fails and the FSM can be forced into a lockdown/error path instead of asserting boot-allowed, closing the skip-COMPARE bypass vector."
    },
    {
      "target_signal": "state",
      "technique": "Redundant majority-voting (TMR) on the FSM state register across three parallel state machines",
      "rationale": "A single-bit transient fault that flips one state copy into DONE is outvoted by the two unaffected replicas, preventing the FSM from ever externally reporting a DONE transition that skipped COMPARE, providing the redundancy required to resist single-event upsets per the fault model."
    }
  ]
}

