  "fsm_states": ["IDLE", "LOAD", "COMPARE", "DONE"],
  "critical_nodes": [
    {
      "signal": "auth_ok",
      "reason": "auth_ok is the flip-flop that directly gates the module's boot-allowed/access-granted output. It is set in the COMPARE state as the result of comparing sig_shift against expected_sig, and is read combinationally/registered to produce the final grant decision.",
      "exploit_scenario": "An attacker injects a single-cycle transient fault that forces auth_ok to 1 either before or independently of the COMPARE state's assignment (auth_ok <= (sig_shift == expected_sig)). Because the boot-allowed output is driven directly from auth_ok once state reaches DONE, forcing auth_ok=1 grants boot access without the signature comparison ever matching. This is a primary, non-data-path bypass vector; it is prioritized above sig_shift/expected_sig/byte_count, which only feed the legitimate comparison and cannot alone flip the final grant."
    }
  ],
  "hardening_recommendations": [
    {
      "target_signal": "auth_ok",
      "technique": "TMR (triple modular redundancy) with majority-voting across three independently-clocked copies of auth_ok",
      "rationale": "A single transient bit-flip in one auth_ok replica is masked by majority voting across the other two copies, so a single-bit fault can no longer silently flip the security-critical pass/fail decision that directly gates the boot-allowed output."
    },
    {
      "target_signal": "auth_ok",
      "technique": "Dual complementary comparators: compute both a match signal (sig_shift == expected_sig) and a mismatch signal (sig_shift != expected_sig) and require match=1 AND mismatch=0 before asserting boot-allowed",
      "rationale": "Forcing auth_ok/match high via a single-bit fault no longer bypasses the check alone because the complementary mismatch invariant must also be independently satisfied; a lone bit-flip that sets match=1 will not simultaneously clear mismatch=0, so the fault is detected rather than silently accepted, directly hardening against the auth_ok bypass scenario."
    },
    {
      "target_signal": "state",
      "technique": "Checksum-based state validation with a complementary encoding check (store state alongside its bitwise complement in a shadow register and flag an error if state != ~shadow_state)",
      "rationale": "A single-bit fault that forces state directly into the DONE encoding will not simultaneously produce the correct complementary value in the shadow register, so the encoding-consistency check fails and the FSM can be forced into a lockdown/error path instead of asserting boot-allowed, closing the skip-COMPARE bypass vector."
    },
    {
      "target_signal": "state",
      "technique": "Redundant majority-voting (TMR) on the FSM state register across three parallel state machines",
      "rationale": "A single-bit transient fault that flips one state copy into DONE is outvoted by the two unaffected replicas, preventing the FSM from ever externally reporting a DONE transition that skipped COMPARE, providing the redundancy required to resist single-event upsets per the fault model."
    }
  ]
}

